  `test_type` enum('Pre-Test','Post-Test') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Pre-Test',
  `target_profile` enum('Instructional','Frustration') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Instructional',
